/* Clinical Intelligence evaluation UI. All clinical state comes from authorized server endpoints.
   Experimental suggestions are never automatically written to a record. */
import {api,segment} from './api.js';
import {esc,attr,link,errorState} from './ui.js';
const a=(x)=>Array.isArray(x)?x:[];
const box=(html)=>`<section class="card space-top-20">${html}</section>`;
const warning=(msg)=>`<div class="notice warning space-top-12">${esc(msg)}</div>`;
const route=(p,c)=>`/doctor/patients/${segment(p)}/clinical-intelligence${c?'?case='+encodeURIComponent(c):''}`;
const getParam=(key)=>new URLSearchParams((location.hash||'').split('?')[1]||'').get(key);
const fetchSafe=async(path)=>{try{return {data:await api.get(path)}}catch(e){return {error:e}}};
const newKey=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'00000000-0000-4000-8000-'+Math.random().toString(16).slice(2).padEnd(12,'0').slice(0,12);
const statusLabels={ready:'Анализ завершён',needs_review:'Требует проверки врача',unavailable:'Анализ пока не выполнен',pending:'В обработке'};
function evidenceList(snapshot,refs){const evidence=a(snapshot?.evidence);return refs?.length?`<div class="small muted">Основание: ${refs.map(ref=>{let item=evidence.find(x=>x.id===ref);return item?`«${esc(item.quote)}»`:'источник изменился';}).join('; ')}</div>`:'';}
function clinicalLinks(items){return a(items).filter(x=>x&&x.kind&&x.id).map(x=>link(`/clinical-library?item=${encodeURIComponent(x.kind+':'+x.id)}`,x.title||'Открыть карточку','secondary')).join(' ');}
function reviewTags(d,reviews){const reviewed=new Map(a(reviews?.items).map(x=>[x.suggestion_id,x]));return a(d.tags).map(t=>{
 const review=reviewed.get(t.suggestion_id),r=review?.review||{};
 return `<div class="list-row"><div class="row-main"><h4>${esc(t.label||t.code||'Метка')}</h4><p class="small muted">${esc(t.category||'Тема')} · ${esc(t.assertion||'')} · ${esc(t.temporality||'')} · ${esc(r.status||'ожидает проверки')}</p>${evidenceList(d,t.evidence_refs)}</div>${t.suggestion_id&&d.permissions?.can_review?`<div class="row"><button class="btn btn-secondary btn-sm" type="button" data-command="ci-review" data-id="${attr(t.suggestion_id)}" data-source="${attr(d.source_version)}" data-revision="${attr(r.revision||0)}" data-correctness="supported">Подтвердить</button><button class="btn btn-quiet btn-sm" type="button" data-command="ci-review" data-id="${attr(t.suggestion_id)}" data-source="${attr(d.source_version)}" data-revision="${attr(r.revision||0)}" data-correctness="unsupported">Отклонить</button></div>`:''}</div>`;
 }).join('')||'<p class="muted">В этом тексте сервер не обнаружил разрешённых меток. Можно запустить повторный анализ после уточнения обращения.</p>';}
function proposalCard(item,snapshot){const map={referral:'Маршрутизация',diagnostic_hypothesis:'Гипотеза для обсуждения',therapy_reference:'Метод терапии',medicine_reference:'Препарат из справочника',safety_illustration:'Иллюстрация сигнала'};
 return `<article class="card inset"><p class="eyebrow">${esc(map[item.type]||'Предложение')} · экспериментальный алгоритм</p><h3>${esc(item.title)}</h3><p>${esc(item.rationale||'')}</p><p class="small muted">${item.category?'Категория: '+esc(item.category)+' · ':''}${item.urgency?'Срочность: '+esc(item.urgency):''}</p>${evidenceList({evidence:a(snapshot.evidence).concat(a(item.evidence))},item.evidence_refs)}<div class="row space-top-12">${clinicalLinks(item.catalog_links)}</div></article>`;}
// Explicitly illustrative preview: no network call and no false persisted patient state.
function exampleClinicalJourney(){return `<section class="card space-top-20" aria-label="Пример поведения Clinical Intelligence"><h2>Интерактивный пример возможностей Clinical Intelligence</h2><p class="small muted">Предзаполненный учебный сценарий. Эти результаты не получены от модели и не сохранены в карте. Для запуска действующего алгоритма выберите пациента выше.</p><details class="space-top-12"><summary><strong>1. Извлечение NLP-меток и оснований</strong></summary><p class="reading">Текст учебного обращения: «Последние две недели стало труднее засыпать, чаще беспокоюсь перед работой, трудно сосредоточиться».</p><div class="list-row"><div class="row-main"><strong>Нарушения сна</strong><p class="small muted">Основание: «стало труднее засыпать» · последние две недели</p></div><span class="pill">Требует проверки</span></div><div class="list-row"><div class="row-main"><strong>Тревожные переживания</strong><p class="small muted">Основание: «чаще беспокоюсь перед работой»</p></div><span class="pill">Требует проверки</span></div><div class="list-row"><div class="row-main"><strong>Сложности концентрации</strong><p class="small muted">Основание: «трудно сосредоточиться»</p></div><span class="pill">Требует проверки</span></div></details><details class="space-top-12"><summary><strong>2. Предложение заполнения карты</strong></summary><p>Черновик: «Пациент сообщает о сложностях засыпания, тревожных переживаниях перед работой и трудностях концентрации в течение примерно двух недель». Источник — текст обращения. Врач редактирует и отдельно подтверждает запись.</p></details><details class="space-top-12"><summary><strong>3. Маршрутизация и объяснение</strong></summary><p>Предложение для обсуждения: оценить необходимость консультации специалиста в зависимости от клинического интервью, выраженности и динамики симптомов. Категория и срочность определяются врачом. На основании одного учебного текста автоматическое направление не создаётся.</p></details><details class="space-top-12"><summary><strong>4. Клинические материалы и опросники</strong></summary><p>При оценке симптомов врач может открыть описания опросников и методы терапии из справочника. Препараты отображаются как справочные материалы, не как назначения.</p><div class="row">${link('/clinical-library?item=instrument:gad_7','GAD-7 · описание','secondary')}${link('/clinical-library?item=instrument:phq_9','PHQ-9 · описание','secondary')}${link('/clinical-library','Открыть полный справочник','secondary')}</div></details><p class="small muted space-top-12">Статус: демонстрация интерфейсной логики. Для настоящего разбора и журналирования используйте авторизованный сценарий с тестовым пациентом.</p></section>`;}
export async function doctorClinicalHub(){const r=await fetchSafe('/api/v1/doctors/me/patients');
 return `<div class="crumbs"><a href="/#/doctor">Рабочий стол врача</a></div><h1 class="page-title">Clinical Copilot</h1><p class="page-intro">Экспериментальные NLP-метки, предложения для записи, маршрутизация и врачебный контроль — на разрешённом обращении.</p>${warning('Результаты демонстрируют техническое поведение моделей и правил, но не являются утверждённой клинической рекомендацией. Действия выполняет врач.')}${box(`<h2>1. Выберите пациента</h2>${r.error?errorState(r.error):a(r.data.items).length?a(r.data.items).map(p=>`<div class="list-row"><div class="row-main"><h4>${esc(p.display_name||'Пациент')}</h4><p class="muted small">Доступ к обращениям дополнительно проверяется сервером</p></div>${link(route(p.id),'Разобрать обращение','primary')}</div>`).join(''):`<p>Доступных пациентов ещё нет. Для полноценной демонстрации создайте тестового пациента, отправьте приглашение, примите согласие и создайте обращение.</p>${link('/doctor/invitations/new','Пригласить пациента','primary')}`}`)}${box(`<h2>2. Независимый тест извлечения тегов</h2><p class="muted">Без пациента и без изменения медицинских записей можно проверить NLP на вымышленном тексте.</p>${link('/doctor/nlp-lab','Открыть лабораторию NLP','secondary')}`)}${exampleClinicalJourney()}`;
}
export async function doctorClinicalCase(patientId){
 const cap=await fetchSafe('/api/v1/clinical-intelligence/capabilities');
 if(cap.error)return `<h1>Clinical Intelligence</h1>${errorState(cap.error)}`;
 const sources=await fetchSafe('/api/v1/clinical-intelligence/patients/'+segment(patientId)+'/sources');
 const selected=getParam('case');const base=route(patientId);
 let header=`<div class="crumbs">${link('/doctor/clinical-copilot','Clinical Copilot')} · ${link('/doctor/patients/'+segment(patientId),'Карточка пациента')}</div><h1 class="page-title">Разбор обращения</h1><p class="page-intro">Источник выбирается врачом. Все основания и разрешения повторно проверяет сервер.</p>${warning('Учебный эксперимент: точность NLP, клинические правила и объяснения требуют отдельного исследования и валидации.')}`;
 if(sources.error)return header+box(`<h2>Доступные обращения</h2>${errorState(sources.error)}<p>Необходима подтверждённая связь с доступом к симптомам и согласие на конкретное обращение.</p>`);
 header+=box(`<div class="row space-between"><h2>Выбранный источник</h2>${link('/doctor/clinical-copilot','К списку пациентов')}</div>${a(sources.data.items).length?a(sources.data.items).map((s,i)=>`<div class="list-row"><div class="row-main"><h4>Обращение ${i+1} · ${esc((s.created_at||'').slice(0,10))}</h4><p class="small muted">${esc(s.source_type||'')}</p></div>${link(route(patientId,s.encounter_ref),selected===s.encounter_ref?'Выбрано':'Открыть',selected===s.encounter_ref?'secondary':'primary')}</div>`).join(''):'<p>Разрешённых обращений нет. Тестовый пациент должен создать обращение этому врачу и подтвердить доступ.</p>'}`);
 if(!selected)return header;
 if(!a(sources.data.items).some(s=>s.encounter_ref===selected))return header+box('<p>Обращение отсутствует в списке разрешённых источников.</p>');
 const q='?encounter_id='+encodeURIComponent(selected);
 const [snap,proposals,reviews,documents,referrals,threads]=await Promise.all([
  fetchSafe('/api/v1/clinical-intelligence/patients/'+segment(patientId)+'/snapshot'+q),
  fetchSafe('/api/v1/clinical-intelligence/patients/'+segment(patientId)+'/proposals'+q),
  fetchSafe('/api/v1/clinical-intelligence/patients/'+segment(patientId)+'/reviews'+q),
  fetchSafe('/api/v1/clinical-workflow/patients/'+segment(patientId)+'/documents'),
  fetchSafe('/api/v1/clinical-intelligence/patients/'+segment(patientId)+'/referrals'+q),
  fetchSafe('/api/v1/clinical-intelligence/patients/'+segment(patientId)+'/threads'+q)
 ]);
 const s=snap.data||{};
 header+=box(`<div class="row space-between"><h2>1. Анализ NLP</h2><span class="pill">${esc(statusLabels[s.analysis_status]||s.analysis_status||'Не запущен')}</span></div>${snap.error?errorState(snap.error):`<p class="small muted">Версия источника: ${esc(s.source_version||'')} · режим ${esc(s.mode||'ещё не выбран')}</p><button class="btn btn-primary" data-command="ci-analyze" data-patient="${attr(patientId)}" data-case="${attr(selected)}" data-version="${attr(s.source_version)}" data-revision="${attr(s.source_revision)}" type="button">${s.analysis_status==='ready'?'Запустить новый анализ':'Запустить анализ'}</button><p class="small muted space-top-12">Никаких автоматических изменений карты. Если локальная модель недоступна, возможен маркированный технический fallback.</p>`}`);
 header+=box(`<h2>2. Метки и проверяемые основания</h2>${snap.error?'<p>Сначала откройте разрешённый источник.</p>':reviewTags(s,reviews.data)}${reviews.error?`<p class="small muted">Проверка меток недоступна: ${esc(reviews.error.message)}</p>`:''}`);
 header+=box(`<h2>3. Предлагаемое заполнение медицинской карты</h2><p class="muted">Фрагменты формируются из выбранного обращения. Перед сохранением врач может полностью изменить текст. Итог остаётся неопубликованным черновиком.</p>${!a(s.draft_suggestions).length?'<p class="small muted">Для предложения текста сначала запустите анализ.</p>':''}<form data-form="ci-document" data-patient="${attr(patientId)}" class="form-stack"><div class="field"><label for="ci-narrative">Текст записи приёма (проверяет врач)</label><textarea id="ci-narrative" name="narrative" maxlength="12000" required rows="5">${esc(a(s.draft_suggestions).map(x=>x.text).join('\n'))}</textarea></div><label class="checkline"><input type="checkbox" name="confirmed" required>Я лично проверил(а) текст и сохраняю черновик, без подписи и публикации</label><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">Сохранить черновик в медицинскую карту</button></form><div class="space-top-12"><h3>Черновики и записи</h3>${documents.error?errorState(documents.error):a(documents.data.items).length?a(documents.data.items).map(x=>`<div class="list-row"><div class="row-main"><strong>${esc(x.kind==='encounter'?'Приём':'План лечения')}</strong><p class="small muted">${esc(x.status)} · ${esc((x.created_at||'').slice(0,10))}</p><p>${esc(x.content?.narrative||'')}</p></div></div>`).join(''):'<p class="muted">Документов пока нет.</p>'}</div>`);
 header+=box(`<h2>4. Маршрутизация, гипотезы и методы</h2><p class="small muted">Категория обязательности, срочность, критичность и клиническое подтверждение — разные признаки.</p>${proposals.error?errorState(proposals.error):a(proposals.data.proposals).length?`<div class="stack">${proposals.data.proposals.map(x=>proposalCard(x,proposals.data)).join('')}</div>`:'<p>Экспериментальные правила не сформировали предложений для этого обращения.</p>'}<h3 class="space-top-20">Решение врача: направление к специалисту</h3><form data-form="ci-referral" data-patient="${attr(patientId)}" data-case="${attr(selected)}" data-source="${attr(s.source_version||proposals.data?.source_version||'')}" data-grant="${attr(proposals.data?.grant_version||'')}" class="form-stack"><div class="field"><label>К кому направить</label><select name="target_specialty"><option value="psychiatrist">Психиатр</option><option value="psychotherapist">Психотерапевт</option><option value="general_practice">Терапевт</option><option value="neurologist">Невролог</option></select></div><div class="row"><div class="field grow"><label>Категория</label><select name="category"><option value="desired">Желательно</option><option value="mandatory">Необходимо по решению врача</option></select></div><div class="field grow"><label>Срочность</label><select name="urgency"><option value="planned">Плановая</option><option value="urgent">Срочная</option><option value="emergency">Неотложная</option></select></div></div><div class="field"><label>Клиническое обоснование врача</label><textarea name="clinical_reason" maxlength="4000" required placeholder="Укажите самостоятельное обоснование, а не только предложение модели"></textarea></div><label class="checkline"><input type="checkbox" name="confirmed" required>Я лично подтверждаю решение</label><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-secondary">Зафиксировать решение</button></form>${referrals.error?`<p class="small muted">Журнал направлений недоступен: ${esc(referrals.error.message)}</p>`:a(referrals.data.items).map(x=>`<p class="small">${esc(x.target_specialty)} · ${esc(x.category)} · ${esc(x.urgency)} · ${esc(x.status)} · ${esc((x.created_at||'').slice(0,10))}</p>`).join('')}`);
 header+=box(`<h2>5. Врачебный чат по выбранному обращению</h2><p class="muted">Отдельная история и проверяемый контекст. Ответы создаёт локальная модель или документированная безопасная заглушка, но не сам интерфейс.</p>${threads.error?errorState(threads.error):`${a(threads.data.items).map(x=>`<div class="list-row"><div class="row-main"><h4>Диалог от ${esc((x.created_at||'').slice(0,16))}</h4></div>${link(`/doctor/patients/${segment(patientId)}/clinical-intelligence/chat/${segment(x.id)}?case=${encodeURIComponent(selected)}`,'Открыть','secondary')}</div>`).join('')}<button class="btn btn-secondary" data-command="ci-create-thread" data-patient="${attr(patientId)}" data-case="${attr(selected)}" data-source="${attr(threads.data.source_version)}" data-grant="${attr(threads.data.grant_version)}" type="button">Новый чат</button>`}`);
 return header;
}
export async function patientAssistant(){
 const sources=await fetchSafe('/api/v1/clinical-intelligence/patient-chat/sources');
 let body=`<div class="crumbs">${link('/patient','Кабинет пациента')}</div><h1 class="page-title">Мой AI-чат</h1><p class="page-intro">Локальная Qwen · только выбранная личная запись и история этого разговора.</p>${warning('Экспериментальный справочный помощник. Ответ не является медицинским заключением или рекомендацией по лечению; врач не получает личный дневник автоматически.')}`;
 if(sources.error)return body+box(`<h2>Локальный помощник</h2>${errorState(sources.error)}<p>Проверьте включение Clinical Intelligence в изолированном Evaluation Sandbox.</p>`);
 body+=box(`<h2>1. Добавьте контекст</h2><form data-form="ci-diary" class="form-stack"><div class="field"><label for="ci-diary-text">Личная учебная запись (только вымышленные данные)</label><textarea name="content" id="ci-diary-text" maxlength="4000" rows="4" required placeholder="Пример: Последние дни сложно уснуть, хочу разобраться, как работает дневник состояния."></textarea></div><label class="checkline"><input type="checkbox" name="confirmed" required>Сохранить личную запись для этого чата</label><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">Создать запись</button></form>`);
 body+=box(`<h2>2. Выберите источник для разговора</h2>${a(sources.data.items).length?a(sources.data.items).map(x=>`<div class="list-row"><div class="row-main"><h4>${esc(x.title||x.source_type)}</h4><p class="small muted">${esc(x.source_type)} · контекст только для этого чата</p></div><button class="btn btn-secondary btn-sm" data-command="ci-patient-thread" data-patient="${attr(sources.data.patient_ref)}" data-case="${attr(x.source_id)}" data-type="${attr(x.source_type)}" data-source="${attr(x.source_version)}" data-grant="${attr(x.grant_version)}">Начать чат</button></div>`).join(''):'<p class="muted">Создайте личную запись выше или собственное обращение. Затем выберите источник.</p>'}`);
 return body;
}
export async function chatView(path,patient){const id=path.split('/').pop();let res=await fetchSafe('/api/v1/clinical-intelligence/threads/'+segment(id));
 if(res.error)return `<h1>История AI-чата</h1>${errorState(res.error)}`;
 const t=res.data,back=patient?'/patient/assistant':`/doctor/patients/${segment(t.patient_ref)}/clinical-intelligence?case=${encodeURIComponent(t.case_ref)}`;
 const messages=a(t.messages).map(m=>`<div class="card inset space-top-12"><p class="eyebrow">${esc(m.role==='user'?'Вы':'AI-помощник')} · ${esc(m.mode||'')} ${m.model?' · '+esc(m.model):''}</p><p class="reading">${esc(m.content||'Ответ ещё готовится.')}</p>${a(m.catalog_citations).length?`<div class="row">${clinicalLinks(m.catalog_citations.map(x=>({...x,id:x.catalog_id,title:x.title||x.catalog_id})))}</div>`:''}</div>`).join('');
 const jobs=a(t.jobs),active=jobs.some(j=>['queued','running'].includes(j.status));
 return `<div class="crumbs">${link(back,'Назад к источнику')}</div><h1 class="page-title">AI-помощник · история разговора</h1>${warning('Экспериментальный модуль. Ответы требуют проверки. История доступна только владельцу, а источник проверяется сервером.')}${box(`<p class="small muted">${esc(t.context_preview?.description||'')} · режим ${esc(t.audience)}</p><div class="stack">${messages||'<p class="muted">Задайте первый вопрос.</p>'}</div>${active?`<div class="notice space-top-12">Ответ формируется локальным сервером. Нажмите «Обновить ответы» через несколько секунд.</div>`:''}<form data-form="ci-message" data-id="${attr(id)}" data-revision="${attr(t.revision)}" data-source="${attr(t.source_version)}" data-grant="${attr(t.grant_version)}" class="form-stack space-top-20"><div class="field"><label>Ваш вопрос</label><textarea name="content" maxlength="2000" rows="3" required placeholder="Например: какие темы есть в выбранной записи?"></textarea></div><p class="error-inline" data-form-error role="alert"></p><div class="row"><button class="btn btn-primary" ${active?'disabled':''}>Отправить вопрос</button><button type="button" class="btn btn-secondary" data-command="ci-chat-refresh">Обновить ответы</button></div></form><p class="small muted">Очередь выполнения: ${jobs.length?esc(jobs.at(-1).status):'пока нет запросов'}</p>`)}`;
}
export async function clinicalFormAction(form,app){const f=new FormData(form),data=Object.fromEntries(f.entries());let destination=null;
 switch(form.dataset.form){
 case 'ci-diary':{
  if(data.confirmed!=='on')throw new Error('Подтвердите сохранение записи.');await api.post('/api/v1/clinical-intelligence/patient-chat/diary',{content:data.content,confirmed:true});destination='/patient/assistant';break;
 }
 case 'ci-document':{
  if(data.confirmed!=='on')throw new Error('Подтвердите врачебную проверку.');const r=await api.post('/api/v1/clinical-workflow/patients/'+segment(form.dataset.patient)+'/documents',{kind:'encounter',mode:'quick',content:{narrative:data.narrative,assessment:'',follow_up:'',diagnoses:[],items:[]}});return {reload:true,message:'Черновик приёма '+r.id+' создан на сервере (не подписан и не опубликован)'};
 }
 case 'ci-referral':{
  if(data.confirmed!=='on')throw new Error('Подтвердите решение врача.');await api.post('/api/v1/clinical-intelligence/patients/'+segment(form.dataset.patient)+'/referrals?encounter_id='+segment(form.dataset.case),{source_version:form.dataset.source,grant_version:form.dataset.grant,authority:'manual_physician',confirmed:true,decision:'create',target_specialty:data.target_specialty,category:data.category,urgency:data.urgency,clinical_reason:data.clinical_reason,idempotency_key:newKey()});return {reload:true,message:'Врачебное решение о направлении сохранено'};
 }
 case 'ci-message':{
  await api.post('/api/v1/clinical-intelligence/threads/'+segment(form.dataset.id)+'/messages',{revision:Number(form.dataset.revision),source_version:form.dataset.source,grant_version:form.dataset.grant,content:data.content,idempotency_key:newKey()});return {reload:true,message:'Вопрос принят сервером в обработку'};
 }
 default:return null;
 }
 return {destination};
}
export async function clinicalCommand(cmd,node){
 if(cmd==='ci-chat-refresh')return {reload:true};
 if(cmd==='ci-analyze'){
  const r=await api.post('/api/v1/clinical-intelligence/patients/'+segment(node.dataset.patient)+'/snapshot?encounter_id='+segment(node.dataset.case),{source_revision:Number(node.dataset.revision),source_version:node.dataset.version});
  return {reload:true,message:r.analysis_status==='ready'?'Метки и основания получены':'Результаты анализа доступны для проверки'};
 }
 if(cmd==='ci-review'){
  await api.post('/api/v1/clinical-intelligence/suggestions/'+segment(node.dataset.id)+'/reviews',{review_revision:Number(node.dataset.revision),source_version:node.dataset.source,correctness:node.dataset.correctness,relevance:'relevant',correction:'',note:'Решение врача в учебном окружении',idempotency_key:newKey()});return {reload:true,message:'Оценка метки сохранена'};
 }
 if(cmd==='ci-create-thread'||cmd==='ci-patient-thread'){
  const isPatient=cmd==='ci-patient-thread';const r=await api.post('/api/v1/clinical-intelligence/patients/'+segment(node.dataset.patient)+'/threads',{encounter_id:node.dataset.case,source_version:node.dataset.source,grant_version:node.dataset.grant,idempotency_key:newKey(),...(isPatient?{source_type:node.dataset.type}:{})});
  return {destination:isPatient?'/patient/assistant/thread/'+segment(r.id):`/doctor/patients/${segment(node.dataset.patient)}/clinical-intelligence/chat/${segment(r.id)}?case=${encodeURIComponent(node.dataset.case)}`};
 }
 return null;
}
export function renderLabSummary(r){
 const facts=a(r.data?.facts);
 const captions={anxiety:'Тревожные переживания',sleep_disturbance:'Нарушения сна',low_mood:'Сниженное настроение',fatigue:'Утомляемость',work:'Работа',family:'Семья',relationships:'Отношения',concentration_difficulty:'Трудности концентрации'};
 return `<div class="space-top-20"><h2>Результат извлечения</h2>${warning('Учебный анализ: это кандидаты для проверки, а не диагнозы. Этот независимый тест не меняет медицинскую карту.')}
 <div class="row"><span class="pill">${esc(r.mode||'режим неизвестен')}</span><span class="pill">${esc(facts.length)} найденных фрагментов</span></div>
 ${r.fallback_used?'<p class="small muted">Локальная модель не ответила; сработал явно обозначенный детерминированный тестовый извлекатель.</p>':''}
 ${facts.length?facts.map(f=>`<div class="list-row"><div class="row-main"><h4>${esc(captions[f.tag_code]||f.tag_code)}</h4><p class="small muted">Основание: «${esc(f.evidence?.quote||'')}» · ${esc(f.assertion)} · ${esc(f.temporality)}</p></div><span class="pill">Предложение</span></div>`).join(''):'<p>Метки не обнаружены: попробуйте учебную фразу с описанием тревожности, нарушения сна или затруднений концентрации.</p>'}
 <p class="small muted">Версия извлекателя: ${esc(r.nlp_version||'')} · ${esc(r.diagnostics?.model_id||'')}. Для демонстрации заполнения карты и маршрутизации используйте Clinical Copilot с разрешённым обращением.</p>
 ${link('/doctor/clinical-copilot','Перейти к Clinical Copilot','secondary')}</div>`;
}
